using System.Collections;
using LittleLeo;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "PurifyEffectBasedAction", menuName = "Data/Battle/Battle Actions/Cellarius/PurifyEffectBased Action")]
public class PurifyEffectBasedAction : BattleAction
{
	[Header("Effect")]
	[SerializeField]
	private Effect effect;

	[Header("Purify Action")]
	[SerializeField]
	private PurifyAction purifyAction;

	[SerializeField]
	private int basePurifyAmount;

	[SerializeField]
	private int effectAmountDivider = 1;

	[SerializeField]
	private bool basePurifyAmountIsAmount;

	[SerializeField]
	private bool enableCurrentCorruptedAnimals = true;

	[SerializeField]
	[ShowIf("enableCurrentCorruptedAnimals")]
	private CurrentCorruptedAnimals currentCorruptedAnimals;

	[Header("VFX")]
	[SerializeField]
	private bool enableVFXDelay;

	[SerializeField]
	[ShowIf("enableVFXDelay")]
	private float vfxDelay;

	public PurifyAction PurifyAction => purifyAction;

	public int BasePurifyAmount => basePurifyAmount;

	public override bool CheckConditionToBeCasted(bool playerHand, DiceOwnerEnum diceOwnerEnum)
	{
		if (basePurifyAmount > 0)
		{
			return true;
		}
		return currentCorruptedAnimals.IsAnyEnemyWithEffect(effect);
	}

	public override void CastTargetAmount(GameObject target, int amount, GameObject source)
	{
		int num = Mathf.CeilToInt((float)target.GetComponent<UnitEffects>().IsEffectActiveGetAmount(effect, activateFeedback: false) / (float)effectAmountDivider) * amount;
		if (num == 0 && basePurifyAmountIsAmount)
		{
			num = amount;
		}
		if (ReferenceSingleton<VFXHandler>.Instance.IsVFXEnabled() && enableVFXDelay)
		{
			ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(CastTargetAmountVFXDelay(target, basePurifyAmount + num, source));
			ReferenceSingleton<GameStateManager>.Instance.SetActionsQueueState();
			return;
		}
		SpawnVFX(GetVFXOwnerPosition(target), 3f);
		if (IsVFXEnabled())
		{
			PlaySFX();
		}
		purifyAction.CastTargetAmount(target, basePurifyAmount + num, source);
		CheckCancelAutoOnDiceCastedOnRuneCasted(source);
	}

	private IEnumerator CastTargetAmountVFXDelay(GameObject target, int amount, GameObject source)
	{
		SpawnVFX(GetVFXOwnerPosition(target), 3f);
		if (IsVFXEnabled())
		{
			PlaySFX();
		}
		yield return new WaitForSeconds(vfxDelay);
		purifyAction.CastTargetAmount(target, amount, source);
		CheckCancelAutoOnDiceCastedOnRuneCasted(source);
	}
}
